scriptLabs.solution:
class Node:
    def __init__(self, k):
        self.k, self.l, self.r = k, None, None

def insert(root, k):
    if root is None:
        return Node(k)
    if k < root.k:
        root.l = insert(root.l, k)
    else:
        root.r = insert(root.r, k)
    return root

def inorder(root, out):
    if root:
        inorder(root.l, out)
        out.append(root.k)
        inorder(root.r, out)

def height(r):
    return 0 if not r else 1 + max(height(r.l), height(r.r))

root = None
for k in [5,3,7,1,9]:
    root = insert(root, k)
out = []
inorder(root, out)
print(out)  # [1, 3, 5, 7, 9] — sorted: the BST invariant

deg = None
for k in range(1000):
    deg = insert(deg, k)
print('degenerate height:', height(deg))  # 1000 — a linked list. This is why AVL/red-black exist.

