def bsearch(xs, target):
    lo, hi = 0, len(xs) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] == target:
            return mid
        elif xs[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def two_sum(xs, target):
    seen = {}
    for i, x in enumerate(xs):
        need = target - x
        if need in seen:
            return [seen[need], i]
        seen[x] = i

